var results = all_items || [];
var found = null;
for (var i = 0; i < results.length; i++) {
    var item = JSON.parse(results[i]);
    if (item.stock === 0) {
        found = { name: item.name, position: i + 1 };
        break;
    }
}
var result;
if (found) {
    result = "⚠️ 发现缺货商品：" + found.name + "（第" + found.position + "个）";
} else {
    result = "✅ 全部有货";
}
({ result: result })
